<script setup>
import {onMounted,ref} from 'vue';import {useAdminAuthStore} from '../stores/adminAuth.js';import {changeCatalogActive,fetchPlatformCatalog} from '../services/adminSession.js'
const auth=useAdminAuthStore(),catalog=ref({niches:[],presets:[]}),error=ref(''),busy=ref('')
async function load(){catalog.value=await fetchPlatformCatalog({apiUrl:import.meta.env.VITE_API_URL||'',accessToken:auth.session.access_token})}
async function toggle(kind,item){const reason=window.prompt(`${item.name} için değişiklik gerekçesi (en az 5 karakter):`);if(!reason)return;busy.value=item.id;error.value='';try{await changeCatalogActive({apiUrl:import.meta.env.VITE_API_URL||'',accessToken:auth.session.access_token,kind,id:item.id,active:!item.isActive,reason});await load()}catch(e){error.value=e.message}finally{busy.value=''}}onMounted(()=>load().catch(()=>error.value='Katalog yüklenemedi.'))
</script>
<template><main class="dashboard"><header><div><div class="eyebrow">İÇERİK KATALOĞU</div><h1>Niche ve banner presetleri</h1></div><RouterLink class="button-link secondary" to="/dashboard">Genel duruma dön</RouterLink></header><p v-if="error" class="notice">{{error}}</p><h2>Niche’ler</h2><section class="panel table-panel"><table><thead><tr><th>Ad</th><th>Anahtar</th><th>Sıra</th><th>Durum</th><th></th></tr></thead><tbody><tr v-for="item in catalog.niches" :key="item.id"><td>{{item.name}}</td><td>{{item.key}}</td><td>{{item.displayOrder}}</td><td>{{item.isActive?'Aktif':'Pasif'}}</td><td><button class="secondary" :disabled="busy===item.id" @click="toggle('niche',item)">{{item.isActive?'Pasifleştir':'Etkinleştir'}}</button></td></tr></tbody></table></section><h2>Banner presetleri</h2><section class="panel table-panel"><table><thead><tr><th>Ad</th><th>Niche</th><th>Başlık</th><th>Durum</th><th></th></tr></thead><tbody><tr v-for="item in catalog.presets" :key="item.id"><td>{{item.name}}</td><td>{{item.nicheName}}</td><td>{{item.title}}</td><td>{{item.isActive?'Aktif':'Pasif'}}</td><td><button class="secondary" :disabled="busy===item.id" @click="toggle('banner_preset',item)">{{item.isActive?'Pasifleştir':'Etkinleştir'}}</button></td></tr></tbody></table></section></main></template>
